BinaryInspector::BinaryInspector(CWnd* owner,std::vector<TrafficRecord> frames,BinaryFrameConfig config):CDialog(IDD_UART_TOOL_FORM,owner),frames_(std::move(frames)),config_(std::move(config)){}
BOOL BinaryInspector::OnInitDialog(){CDialog::OnInitDialog();SetWindowTextW(L"Binary field inspector - retained snapshot");font_=make_ui_font(m_hWnd,std::wstring(AfxGetApp()->m_lpCmdLine).find(L"--font125")!=std::wstring::npos);
    const auto child=[&](const wchar_t* cls,const wchar_t* name,DWORD style,int id){auto h=::CreateWindowW(cls,name,WS_CHILD|WS_VISIBLE|style,0,0,1,1,m_hWnd,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),nullptr,nullptr);::SendMessageW(h,WM_SETFONT,reinterpret_cast<WPARAM>(font_),FALSE);return h;};
    pick_=child(L"COMBOBOX",L"",CBS_DROPDOWNLIST|WS_VSCROLL|WS_TABSTOP,10);edit_=child(L"BUTTON",L"Bits / enums...",BS_PUSHBUTTON|WS_TABSTOP,11);close_=child(L"BUTTON",L"Close",BS_PUSHBUTTON|WS_TABSTOP,IDCANCEL);
    list_=child(WC_LISTVIEWW,L"",LVS_REPORT|LVS_SINGLESEL|WS_BORDER|WS_TABSTOP,12);ListView_SetExtendedListViewStyle(list_,LVS_EX_FULLROWSELECT|LVS_EX_DOUBLEBUFFER);
    const wchar_t* headers[]={L"Field",L"Offset, bytes",L"Type",L"Value"};for(int n=0;n<4;++n){LVCOLUMNW col{};col.mask=LVCF_TEXT|LVCF_WIDTH;col.pszText=const_cast<wchar_t*>(headers[n]);col.cx=n==3?280:180;ListView_InsertColumn(list_,n,&col);}
    hex_=child(L"EDIT",L"",ES_READONLY|ES_MULTILINE|ES_NOHIDESEL|ES_AUTOHSCROLL|WS_HSCROLL|WS_VSCROLL|WS_BORDER|WS_TABSTOP,13);::SendMessageW(hex_,EM_SETLIMITTEXT,1024*1024,0);status_=child(L"STATIC",L"",SS_NOPREFIX,14);
    LOGFONTW lf{};GetObjectW(font_,sizeof(lf),&lf);wcscpy_s(lf.lfFaceName,L"Consolas");mono_=CreateFontIndirectW(&lf);::SendMessageW(hex_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_?mono_:font_),FALSE);
    for(size_t i=0;i<frames_.size();++i){const auto label=std::to_wstring(i+1)+L". "+(frames_[i].tx?L"TX ":L"RX ")+std::to_wstring(frames_[i].bytes.size())+L" bytes / receipt ms "+std::to_wstring(frames_[i].receipt_ms);::SendMessageW(pick_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(label.c_str()));}
    ::SendMessageW(pick_,CB_SETCURSEL,frames_.empty()?-1:frames_.size()-1,0);SetWindowPos(nullptr,70,50,1000,750,SWP_NOZORDER);layout();rebuild();return TRUE;
}
void BinaryInspector::rebuild(){const auto index=::SendMessageW(pick_,CB_GETCURSEL,0,0);if(index<0||static_cast<size_t>(index)>=frames_.size())return;const auto& bytes=frames_[index].bytes;rows_=inspect_binary(bytes,config_,bits_);ListView_DeleteAllItems(list_);
    for(size_t i=0;i<rows_.size();++i){const auto name=uart_wide(rows_[i].name),type=uart_wide(rows_[i].type),value=uart_wide(rows_[i].value),range=L"["+std::to_wstring(rows_[i].offset)+L", "+std::to_wstring(rows_[i].count)+L"]";LVITEMW item{};item.mask=LVIF_TEXT;item.iItem=static_cast<int>(i);item.pszText=const_cast<wchar_t*>(name.c_str());ListView_InsertItem(list_,&item);ListView_SetItemText(list_,item.iItem,1,const_cast<wchar_t*>(range.c_str()));ListView_SetItemText(list_,item.iItem,2,const_cast<wchar_t*>(type.c_str()));ListView_SetItemText(list_,item.iItem,3,const_cast<wchar_t*>(value.c_str()));}
    positions_.clear();std::wstring hex;for(size_t i=0;i<bytes.size();++i){if(i%16==0){wchar_t offset[32]{};swprintf_s(offset,L"%08X  ",static_cast<unsigned>(i));hex+=offset;}positions_.push_back(static_cast<int>(hex.size()));hex+=uart_wide(uart_hex(std::string_view(bytes).substr(i,1)));hex+=(i%16==15?L"\r\n":L" ");}::SetWindowTextW(hex_,hex.c_str());
    auto status=uart_wide(inspect_checksum(bytes,config_))+L"\r\nSelect a field to highlight its source bytes. Snapshot only; no transmission or file edits.";if(config_.fixed_bytes&&bytes.size()!=config_.fixed_bytes)status=L"Selected chunk length differs from configured frame size.\r\n"+status;::SetWindowTextW(status_,status.c_str());
}
BOOL BinaryInspector::OnNotify(WPARAM w,LPARAM l,LRESULT* result){const auto h=reinterpret_cast<NMHDR*>(l);if(h&&h->hwndFrom==list_&&h->code==LVN_ITEMCHANGED){const auto info=reinterpret_cast<NMLISTVIEW*>(l);if(info->iItem>=0&&static_cast<size_t>(info->iItem)<rows_.size()&&(info->uNewState&LVIS_SELECTED)){const auto& row=rows_[info->iItem];if(row.valid&&row.count&&row.offset<positions_.size()&&row.count<=positions_.size()-row.offset){::SendMessageW(hex_,EM_SETSEL,positions_[row.offset],positions_[row.offset+row.count-1]+2);::SendMessageW(hex_,EM_SCROLLCARET,0,0);}}*result=0;return TRUE;}return CDialog::OnNotify(w,l,result);}
BOOL BinaryInspector::OnCommand(WPARAM w,LPARAM l){if(LOWORD(w)==10&&HIWORD(w)==CBN_SELCHANGE){rebuild();return TRUE;}if(LOWORD(w)==11&&HIWORD(w)==BN_CLICKED){UartToolForm form(L"Read-only bitfields / enums",L"CSV: name,byte_offset,u8/u16le/u16be/u32le/u32be,first_bit,bit_count,enum. Example: state,2,u16le,0,2,0=OFF|1=ON. LSB is bit 0 after endian decoding. Empty definitions clear optional rows. No source bytes are modified.",{{L"Bit definitions",definitions_,{},10}},{},[](const auto& f,std::wstring& e){std::vector<BitField> bits;std::string error;const bool ok=parse_bit_fields(message_utf8(f[0]),bits,error);e=uart_wide(error);return ok;},this);if(form.DoModal()==IDOK){std::string error;definitions_=form.values()[0];parse_bit_fields(message_utf8(definitions_),bits_,error);rebuild();}return TRUE;}return CDialog::OnCommand(w,l);}
void BinaryInspector::layout(){if(!list_)return;CRect r;GetClientRect(&r);const int row=std::max(30,static_cast<int>(GetDpiForWindow(m_hWnd))*30/96);::MoveWindow(pick_,10,10,std::max(100,r.Width()-310),row*10,TRUE);::MoveWindow(edit_,r.right-290,10,170,row,TRUE);::MoveWindow(close_,r.right-110,10,100,row,TRUE);const int top=row+20,mid=top+(r.Height()-top-row*3)/2;::MoveWindow(list_,10,top,r.Width()-20,std::max(row*3,mid-top),TRUE);::MoveWindow(hex_,10,mid+10,r.Width()-20,std::max<int>(row*3,r.bottom-mid-row*3-20),TRUE);::MoveWindow(status_,10,r.bottom-row*3-5,r.Width()-20,row*3,TRUE);}
void BinaryInspector::OnSize(UINT t,int w,int h){CDialog::OnSize(t,w,h);if(t!=SIZE_MINIMIZED)layout();}
void BinaryInspector::OnGetMinMaxInfo(MINMAXINFO* i){CDialog::OnGetMinMaxInfo(i);i->ptMinTrackSize.x=850;i->ptMinTrackSize.y=650;}
LRESULT BinaryInspector::OnDpiChanged(WPARAM,LPARAM l){const auto next=make_ui_font(m_hWnd);if(next){LOGFONTW lf{};GetObjectW(next,sizeof(lf),&lf);wcscpy_s(lf.lfFaceName,L"Consolas");const auto mono=CreateFontIndirectW(&lf);const auto old=font_,old_mono=mono_;font_=next;mono_=mono?mono:next;::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));::SendMessageW(hex_,WM_SETFONT,reinterpret_cast<WPARAM>(mono_),FALSE);if(old_mono&&old_mono!=old)DeleteObject(old_mono);if(old)DeleteObject(old);}if(l){const auto r=reinterpret_cast<RECT*>(l);SetWindowPos(nullptr,r->left,r->top,r->right-r->left,r->bottom-r->top,SWP_NOZORDER|SWP_NOACTIVATE);}layout();return 0;}
void BinaryInspector::OnDestroy(){for(auto h=::GetWindow(m_hWnd,GW_CHILD);h;){const auto next=::GetWindow(h,GW_HWNDNEXT);::DestroyWindow(h);h=next;}CDialog::OnDestroy();if(mono_&&mono_!=font_)DeleteObject(mono_);if(font_)DeleteObject(font_);mono_=font_=nullptr;}
